select m.warehouse_id,m.warehouse_name,m.sku_id,m.sku_no,m.spu_no, m.purchase_instock_qty,m.inventory_profit_instock_qty,m.other_instock_qty,m.sale_return_qty,m.transfer_instock_qty,m.machine_instock_qty, m.purchase_return_qty,m.transfer_outstock_qty,m.sale_outstock_qty,m.other_outstock_qty,m.inventory_loss_outstock_qty,m.machine_outstock_qty from ( select tf.warehouse_id,max(tf.warehouse_name) as warehouse_name,tf.sku_id,max(tf.sku_no) as sku_no ,max(pi.spu_no) as spu_no, sum(case when tf.dict_biz_type in('02','03') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as purchase_instock_qty, -- 采购入库 sum(case when tf.dict_biz_type in ('13') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as inventory_profit_instock_qty, -- 盘盈入库 sum(case when tf.dict_biz_type in ('19') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as other_instock_qty, -- 其他入库 sum(case when tf.dict_biz_type in ('12') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as sale_return_qty, -- 销售退货入库 sum(case when tf.dict_biz_type in ('07','26') and tf.dict_inventory_status = 'usable' and ((tf.operation_mode in ('approve', 'amend') and tf.qty > 0) or (tf.operation_mode = 'unApprove' and tf.qty < 0) ) then tf.qty -- 直接调拨单（新增）目的仓可用增加；直接调拨单（调拨申请单下推）目的仓可用增加 when tf.dict_biz_type in ('09') and tf.dict_inventory_status = 'usable' then tf.qty else 0 -- 分步式调拨调入目的仓可用增加 end) as transfer_instock_qty, -- 调拨入库 sum(case when tf.dict_biz_type in ('17','24') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as machine_instock_qty, -- 加工入库
sum(case when tf.dict_biz_type in('04','05') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as purchase_return_qty, -- 采购退货出库 sum(case when tf.dict_biz_type in('07') and tf.dict_inventory_status = 'usable' and ((tf.operation_mode in ('approve', 'amend') and tf.qty < 0) or (tf.operation_mode = 'unApprove' and tf.qty > 0) ) then tf.qty -- 直接调拨单（新增）当前仓可用减少； when tf.dict_biz_type in('26','08') and tf.dict_inventory_status = 'frozen' then tf.qty else 0 end) as -- 直接调拨单（调拨申请单下推），分布式调拨调出当前仓冻结减少 transfer_outstock_qty, -- 调拨出库（分布式调拨出库单，冻结减少） sum(case when tf.dict_biz_type in('11') and tf.dict_inventory_status = 'frozen' then tf.qty else 0 end) as sale_outstock_qty, -- 销售出库（销售出库，冻结减少） sum(case when tf.dict_biz_type in('20') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as other_outstock_qty, -- 其他出库 sum(case when tf.dict_biz_type in('14') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as inventory_loss_outstock_qty, -- 盘亏出库 sum(case when tf.dict_biz_type in('18','23') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as machine_outstock_qty -- 加工出库 from transaction_flow tf left join product_detail pd on pd.id = tf.sku_id left join product_info pi on pd.product_id = pi.id
tf.is_deleted = false
and tf.sku_no in
#{item}
and pi.spu_no in
#{item}
and tf.warehouse_id in
#{item}
and tf.trade_time >= #{params.dateList[0]} and (#{params.dateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > tf.trade_time
${params.permissionSql}
group by tf.warehouse_id, tf.sku_id ) m ORDER BY m.warehouse_name asc,m.sku_no asc

select m.warehouse_id,m.warehouse_name,m.sku_id,m.sku_no,m.spu_no, m.purchase_instock_qty,m.inventory_profit_instock_qty,m.other_instock_qty,m.sale_return_qty,m.transfer_instock_qty,m.machine_instock_qty, m.purchase_return_qty,m.transfer_outstock_qty,m.sale_outstock_qty,m.other_outstock_qty,m.inventory_loss_outstock_qty,m.machine_outstock_qty from ( select tf.warehouse_id,max(tf.warehouse_name) as warehouse_name,tf.sku_id,max(tf.sku_no) as sku_no ,max(pi.spu_no) as spu_no, sum(case when tf.dict_biz_type in('02','03') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as purchase_instock_qty, -- 采购入库 sum(case when tf.dict_biz_type in ('13') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as inventory_profit_instock_qty, -- 盘盈入库 sum(case when tf.dict_biz_type in ('19') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as other_instock_qty, -- 其他入库 sum(case when tf.dict_biz_type in ('12') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as sale_return_qty, -- 销售退货入库 sum(case when tf.dict_biz_type in ('07','26') and tf.dict_inventory_status = 'usable' and ((tf.operation_mode in ('approve', 'amend') and tf.qty > 0) or (tf.operation_mode = 'unApprove' and tf.qty < 0) ) then tf.qty when tf.dict_biz_type in ('09') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as transfer_instock_qty, -- 调拨入库 sum(case when tf.dict_biz_type in ('17','24') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as machine_instock_qty, -- 加工入库
sum(case when tf.dict_biz_type in('04','05') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as purchase_return_qty, -- 采购退货出库 sum(case when tf.dict_biz_type in('07') and tf.dict_inventory_status = 'usable' and ((tf.operation_mode in ('approve', 'amend') and tf.qty < 0) or (tf.operation_mode = 'unApprove' and tf.qty > 0) ) then tf.qty when tf.dict_biz_type in('26','08') and tf.dict_inventory_status = 'frozen' and ((tf.operation_mode in ('approve', 'amend') and tf.qty < 0) or (tf.operation_mode = 'unApprove' and tf.qty > 0) ) then tf.qty else 0 end) as transfer_outstock_qty, -- 调拨出库（分布式调拨出库单，冻结减少） sum(case when tf.dict_biz_type in('11') and tf.dict_inventory_status = 'frozen' then tf.qty else 0 end) as sale_outstock_qty, -- 销售出库（销售出库，冻结减少） sum(case when tf.dict_biz_type in('20') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as other_outstock_qty, -- 其他出库 sum(case when tf.dict_biz_type in('14') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as inventory_loss_outstock_qty, -- 盘亏出库 sum(case when tf.dict_biz_type in('18','23') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as machine_outstock_qty -- 加工出库 from transaction_flow tf left join product_detail pd on pd.id = tf.sku_id left join product_info pi on pd.product_id = pi.id
tf.is_deleted = false
and tf.sku_no in
#{item}
and pi.spu_no in
#{item}
and tf.warehouse_id in
#{item}
and tf.trade_time >= #{params.dateList[0]} and (#{params.dateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > tf.trade_time
${params.permissionSql}
group by tf.warehouse_id, tf.sku_id ) m ORDER BY m.warehouse_name asc,m.sku_no asc

select n.warehouse_id,n.org_id,n.warehouse_name,n.sku_id,n.sku_no,n.spu_no,n.sale_state,n.product_name,n.product_img_url, n.purchase_qty,n.transfer_qty,n.transport_qty from ( select m.warehouse_id,m.org_id,m.warehouse_name,m.sku_id,m.sku_no,m.spu_no,m.sale_state,m.product_name,m.product_img_url, case when m.purchase_qty < 0 then 0 else m.purchase_qty end as purchase_qty, case when m.transfer_qty < 0 then 0 else m.transfer_qty end as transfer_qty, purchase_qty + transfer_qty as transport_qty from ( select tf.warehouse_id, tf.sku_id, max(tf.warehouse_name) as warehouse_name, max(tf.org_id) as org_id, max(tf.sku_no) as sku_no , max(pi.spu_no) as spu_no, max(ps.sale_state) as sale_state, max(pd.name) as product_name, max(pd.images_url) as product_img_url, sum(case when tf.dict_biz_type in ('21','01','03','04','25','27','28') and tf.dict_inventory_status = 'inTransit' then tf.qty else 0 end) as purchase_qty, -- 采购在途 sum(case when tf.dict_biz_type in ('08','09') and tf.dict_inventory_status = 'inTransit' then tf.qty else 0 end) as transfer_qty -- 调拨在途 from transaction_flow tf left join product_detail pd on pd.id = tf.sku_id left join product_info pi on pd.product_id = pi.id left join product_sale ps on ps.sku_id = pd.id
tf.is_deleted = false
and tf.sku_no in
#{item}
and pi.spu_no in
#{item}
and tf.warehouse_id in
#{item}
and tf.org_id in
#{item}
and ps.sale_state in
#{item}
${params.permissionSql}
group by tf.warehouse_id, tf.sku_id ) m ) n ORDER BY n.warehouse_name asc,n.transport_qty desc

select n.warehouse_id,n.org_id,n.warehouse_name,n.sku_id,n.sku_no,n.spu_no,n.sale_state,n.product_name,n.product_img_url, n.purchase_qty,n.transfer_qty,n.transport_qty from ( select m.warehouse_id,m.org_id,m.warehouse_name,m.sku_id,m.sku_no,m.spu_no,m.sale_state,m.product_name,m.product_img_url, case when m.purchase_qty < 0 then 0 else m.purchase_qty end as purchase_qty, case when m.transfer_qty < 0 then 0 else m.transfer_qty end as transfer_qty, purchase_qty + transfer_qty as transport_qty from ( select tf.warehouse_id, tf.sku_id, max(tf.warehouse_name) as warehouse_name, max(tf.org_id) as org_id, max(tf.sku_no) as sku_no , max(pi.spu_no) as spu_no, max(ps.sale_state) as sale_state, max(pd.name) as product_name, max(pd.images_url) as product_img_url, sum(case when tf.dict_biz_type in ('21','01','03','04','25','27','28') and tf.dict_inventory_status = 'inTransit' then tf.qty else 0 end) as purchase_qty, -- 采购在途 sum(case when tf.dict_biz_type in ('08','09') and tf.dict_inventory_status = 'inTransit' then tf.qty else 0 end) as transfer_qty -- 调拨在途 from transaction_flow tf left join product_detail pd on pd.id = tf.sku_id left join product_info pi on pd.product_id = pi.id left join product_sale ps on ps.sku_id = pd.id
tf.is_deleted = false
and tf.sku_id in
#{item}
and tf.sku_no in
#{item}
and pi.spu_no in
#{item}
and tf.warehouse_id in
#{item}
and tf.org_id in
#{item}
and ps.sale_state in
#{item}
${params.permissionSql}
group by tf.warehouse_id, tf.sku_id ) m ) n ORDER BY n.warehouse_name asc,n.transport_qty desc
